const BY_ID: ReadonlyMap<string, AttributeDef> = new Map(ATTRIBUTES.map((d) => [d.id, d]));

/** 按规范标识查找属性定义。 */
export function lookupAttribute(id: string): AttributeDef | undefined {
  return BY_ID.get(id);
}

/** 已登记属性数量。 */
export function attributeCount(): number {
  return ATTRIBUTES.length;
}

/** 真源版本号，供控制台提示与诊断。 */
export const REGISTRY_VERSION = 1;
